import bpy, math, mathutils
from mathutils import Matrix, Vector

# ---- helpers preamble (redefined each call) ----
def gm(name):
    return bpy.data.materials[name]
def apply_mat(o, m):
    if o.data and hasattr(o.data,'materials'):
        o.data.materials.clear(); o.data.materials.append(m)
    return o
def box(name, dims, loc=(0,0,0), material=None, bevel=0.0):
    bpy.ops.mesh.primitive_cube_add(location=loc)
    o = bpy.context.active_object; o.name=name; o.dimensions=dims
    bpy.ops.object.transform_apply(scale=True)
    if bevel>0:
        mod=o.modifiers.new("bev","BEVEL"); mod.width=bevel; mod.segments=2
    if material: apply_mat(o, material)
    return o
def cyl(name, r1, depth, loc=(0,0,0), material=None, verts=20, r2=None):
    if r2 is None:
        bpy.ops.mesh.primitive_cylinder_add(vertices=verts, radius=r1, depth=depth, location=loc)
    else:
        bpy.ops.mesh.primitive_cone_add(vertices=verts, radius1=r1, radius2=r2, depth=depth, location=loc)
    o=bpy.context.active_object; o.name=name
    if material: apply_mat(o, material)
    return o
def place(o, x,y,z, yaw=0.0, rx=0.0, ry=0.0):
    T=Matrix.Translation((x,y,z)); R=Matrix.Rotation(yaw,4,'Z')@Matrix.Rotation(rx,4,'X')@Matrix.Rotation(ry,4,'Y')
    o.matrix_world = T@R; return o
def parent_to(objs, parent):
    for o in objs: o.parent=parent
    return parent
def empty(name):
    o=bpy.data.objects.new(name, None); bpy.context.collection.objects.link(o); return o

